const e = $input.first().json;
const esc = x => String(x ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;');
return [{ json: {
  empfaenger: '', // hier Alert-Adresse eintragen
  betreff: '🚨 AutoScan AI: Workflow abgebrochen',
  html: `<p><b>Der Workflow ${esc(e.workflow?.name)} ist abgebrochen.</b></p><p>Execution: ${esc(e.execution?.id)}<br>Node: ${esc(e.execution?.lastNodeExecuted)}<br>Fehler: ${esc(e.execution?.error?.message)}</p><p><a href="${esc(e.execution?.url)}">Execution öffnen</a></p>`,
} }];
